SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "杨师立自杀，郑君雄以其首出降", "start_year": 884, "end_year": 884, "time_original": "中和四年六月壬辰奏报；围城经过历时未详", "dynasty": "唐", "description": "高仁厚围梓州，致书城内劝降。郑君雄率众入府，杨师立自杀；郑君雄携首出降。", "phases": [], "location_name": "梓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4ad79a39-48c2-5fd4-b67a-c70bb55f62ad"}, {"title": "陈敬瑄处死杨师立之子", "start_year": 884, "end_year": 884, "time_original": "杨师立死后；具体日未载", "dynasty": "唐", "description": "陈敬瑄命人将杨师立之子钉于城北。", "phases": [], "location_name": "城北", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "56b989e4-713d-5e5b-8c4a-e3f6fc4b4a05"}, {"title": "高仁厚获任东川节度使", "start_year": 884, "end_year": 884, "time_original": "中和四年六月条，具体日未载", "dynasty": "唐", "description": "朝廷以高仁厚为东川节度使。", "phases": [], "location_name": "东川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "03a1cfb1-bbb9-5eb8-85e7-fe607e87f337"}, {"title": "李师悦、尚让于瑕丘败黄巢", "start_year": 884, "end_year": 884, "time_original": "中和四年六月甲辰", "dynasty": "唐", "description": "李师悦与尚让追黄巢至瑕丘并击败之；黄巢逃至狼虎谷。", "phases": [], "location_name": "瑕丘", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "50264e8c-a249-5b2c-bb32-5f16e5b1af75"}, {"title": "林言斩黄巢及其家人首，随后被沙陀博野军所杀", "start_year": 884, "end_year": 884, "time_original": "中和四年六月丙午", "dynasty": "唐", "description": "《通鉴》记黄巢外甥林言斩黄巢兄弟及妻子之首，拟献时溥；途中沙陀博野军夺首，杀林言并献时溥。", "phases": [], "location_name": "狼虎谷一带", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "71ecc7b2-0689-5c5f-af0c-748d2f2d28b2"}, {"title": "朱瑾救朱全忠，于合乡败秦宗权", "start_year": 884, "end_year": 884, "time_original": "中和四年六月条；具体月日未载", "dynasty": "唐", "description": "秦宗权攻宣武节度使朱全忠。朱全忠向朱瑄求援；朱瑄派朱瑾率军赴援，于合乡击败秦宗权。", "phases": [], "location_name": "合乡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cc4f3c92-0b40-5910-a5b5-e123e9a76802"}, {"title": "时溥献黄巢等首，俘虏姬妾遭处决", "start_year": 884, "end_year": 884, "time_original": "中和四年七月壬午", "dynasty": "唐", "description": "时溥遣使献黄巢及家人首级和姬妾。皇帝在大玄楼受献并讯问；一名未记姓名的姬妾反诘后，众姬妾皆被处决。", "phases": [], "location_name": "大玄楼及市", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "49f45a62-4b0d-5f7a-a097-de6440c7760f"}, {"title": "朱全忠于溵水战秦宗权", "start_year": 884, "end_year": 884, "time_original": "中和四年七月条；具体日未载", "dynasty": "唐", "description": "《通鉴》电子底本记朱全忠击秦宗权，并称在溵水取胜；“败示权”中的“示”疑为转录讹字，胜败对象依上下文待校。", "phases": [], "location_name": "溵水", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5a83e236-5667-52a5-a523-1101eb084e94"}, {"title": "李克用上表控诉朱全忠，朝廷劝解", "start_year": 884, "end_year": 884, "time_original": "中和四年七月后条；八表先后时间未载", "dynasty": "唐", "description": "李克用回晋阳后整备甲兵，遣李承嗣上表，指控朱全忠谋害自己并求朝廷削其官爵。朝廷遣使劝和，李克用先后上表八次，仍未获准讨伐。", "phases": [], "location_name": "晋阳、行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4aba3db5-9ea7-5a70-b925-875eb3f33212"}, {"title": "李克用八月奏请麟州、昭义及云蔚归属", "start_year": 884, "end_year": 884, "time_original": "中和四年八月", "dynasty": "唐", "description": "李克用请麟州隶河东、弟李克修任昭义节度使，均获准；又奏罢云蔚防御使，使其依旧隶河东，亦获准。朝廷进李克用爵陇西郡王。", "phases": [], "location_name": "麟州、昭义、云蔚", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1fbdeb7e-6753-5ea9-97f0-6415fcfbf519"}, {"title": "朱全忠加同平章事", "start_year": 884, "end_year": 884, "time_original": "中和四年九月己未", "dynasty": "唐", "description": "朱全忠加同平章事。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "6e59c4fb-79f8-5f2d-9436-e321b6ed43aa"}, {"title": "王徽知京兆尹，修治长安宫室", "start_year": 884, "end_year": 884, "time_original": "中和四年九月后、十月前条；具体日未载", "dynasty": "唐", "description": "王徽知京兆尹事，招抚流散人口、修缮宫室，使百司事务渐有头绪。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "490df0ac-4dd2-56b0-bc03-4ba09f9dc060"}, {"title": "关东藩镇上表请僖宗返京", "start_year": 884, "end_year": 884, "time_original": "中和四年十月", "dynasty": "唐", "description": "关东藩镇上表请求皇帝返回长安。", "phases": [], "location_name": "关东、长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "92efe9c7-b15f-59c6-9256-95aa39687217"}, {"title": "王铎请还朝，徙义昌节度使", "start_year": null, "end_year": null, "time_original": "卷256中和四年追叙；确年待考", "dynasty": "唐", "description": "《通鉴》追叙：朱全忠初镇大梁时对王铎礼敬，后兵势渐强；王铎认为不足倚靠，上表请还朝，朝廷徙其为义昌节度使。", "phases": [], "location_name": "义昌", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a7979a17-0b6c-5c6f-b7d7-43544e54c027"}, {"title": "王建等五将离鹿晏弘奔行在", "start_year": 884, "end_year": 884, "time_original": "中和四年十一月", "dynasty": "唐", "description": "王建、韩建、张造、晋晖、李师泰率众数千离开鹿晏弘，奔赴行在。田令孜收五人为假子，任诸卫将军，编为随驾五都。", "phases": [], "location_name": "兴元、行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8ac162fe-7a5f-57c8-a3c4-621647d0a9b8"}, {"title": "鹿晏弘弃兴元东走", "start_year": 884, "end_year": 884, "time_original": "中和四年十一月，五将奔行在之后", "dynasty": "唐", "description": "田令孜遣禁兵讨鹿晏弘；鹿晏弘率众弃兴元逃走。", "phases": [], "location_name": "兴元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2deb2546-46a7-589e-805b-a4639ed09afe"}, {"title": "曹知悫在黄巢陷长安后据嵯峨山抗敌", "start_year": null, "end_year": null, "time_original": "黄巢陷长安后；具体年待考", "dynasty": "唐", "description": "曹知悫聚集壮士据嵯峨山南自保，并数次夜入长安袭黄巢军营。", "phases": [], "location_name": "嵯峨山、长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2fcbe1b9-3047-518e-af9a-146c61a24be0"}, {"title": "王行瑜奉田令孜密令袭杀曹知悫", "start_year": 884, "end_year": 884, "time_original": "车驾将还长安之时；确日未载", "dynasty": "唐", "description": "田令孜厌恶曹知悫，密令王行瑜诛杀；王行瑜出兵袭击，曹知悫一营尽死。", "phases": [], "location_name": "嵯峨山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "19ebd98d-2a7d-5f42-9d53-ca7cc46fd6a2"}, {"title": "鹿晏弘与秦宗权部攻陷襄州", "start_year": 884, "end_year": 884, "time_original": "中和四年十一月后条；确日未载", "dynasty": "唐", "description": "鹿晏弘出兵襄州；秦宗权遣秦诰、赵德諲会合，攻陷襄州。山南东道节度使刘臣容奔成都。", "phases": [], "location_name": "襄州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7c6bac73-9264-5b85-90c6-0ff4dc81f62e"}, {"title": "鹿晏弘据许州并获任忠武节度使", "start_year": 884, "end_year": 884, "time_original": "襄州陷后；具体日未载", "dynasty": "唐", "description": "鹿晏弘转掠各州后进入许州；周岌弃镇，鹿晏弘自称留后。朝廷无力讨伐，任其为忠武节度使。", "phases": [], "location_name": "许州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "49022b91-647c-5893-af2a-5298dc676dfa"}, {"title": "陈敬瑄辞三川军事职", "start_year": 884, "end_year": 884, "time_original": "中和四年十二月己丑", "dynasty": "唐", "description": "陈敬瑄上表辞三川都指挥、招讨、制置、安抚等使，朝廷准许。", "phases": [], "location_name": "三川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2ed608a8-28da-5efc-88e6-f0997615b77b"}, {"title": "陈岩兴九龙军并击退李连", "start_year": null, "end_year": null, "time_original": "黄巢转掠福建时及其后；确年待考", "dynasty": "唐", "description": "《通鉴》追叙陈岩聚乡众号九龙军，郑镒奏其为团练副使；李连后来攻福州，陈岩击败之。", "phases": [], "location_name": "福建、福州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "37975880-e7a6-5da1-a757-a400734c45c6"}, {"title": "陈岩任福建观察使", "start_year": 884, "end_year": 884, "time_original": "中和四年十二月壬寅", "dynasty": "唐", "description": "郑镒上表请陈岩接任，朝廷以陈岩为福建观察使。", "phases": [], "location_name": "福建", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c509bb2a-ff36-5383-8ef1-3c10497c5ab4"}, {"title": "乐从训伏杀王铎，乐彦祯称其为盗所杀", "start_year": 884, "end_year": 884, "time_original": "中和四年十二月条；具体日未载", "dynasty": "唐", "description": "乐从训伏兵杀过魏州的王铎及宾僚从者，并掠其资装；乐彦祯向朝廷上报称王铎为盗所杀。", "phases": [], "location_name": "高鸡泊", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ee6a56d6-e321-5e1b-8c0e-61dfb6550a01"}, {"title": "邠宁军获赐号静难", "start_year": 884, "end_year": 884, "time_original": "中和四年十二月条；具体日未载", "dynasty": "唐", "description": "朝廷赐邠宁军号“静难”。", "phases": [], "location_name": "邠宁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "14f0e0bd-6196-5dd4-86b4-0a762f4b5e7e"}, {"title": "陈晟逐柳超并获任睦州刺史", "start_year": 884, "end_year": 884, "time_original": "中和四年是岁；具体月日未载", "dynasty": "唐", "description": "馀杭镇使陈晟逐睦州刺史柳超，自领州事；朝廷任陈晟为刺史。", "phases": [], "location_name": "睦州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fea27d41-160d-5bab-ab85-8f468e408645"}, {"title": "王敬荛逐颍州刺史并获任命", "start_year": 884, "end_year": 884, "time_original": "中和四年是岁；具体月日未载", "dynasty": "唐", "description": "颍州都知兵马使王敬荛逐原刺史、自领州事；朝廷任其为刺史。原刺史姓名未载。", "phases": [], "location_name": "颍州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "09c76dee-0e63-5e72-a963-55a2921ff966"}, {"title": "冯行袭设伏斩孙喜并任均州刺史", "start_year": 884, "end_year": 884, "time_original": "中和四年是岁条；具体月日未载", "dynasty": "唐", "description": "孙喜欲攻均州，冯行袭设计令其单独渡江，伏兵起后斩孙喜；山南东道节度使上奏其功，朝廷任冯行袭为均州刺史。", "phases": [], "location_name": "均州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7a11f0ad-a2e5-583f-b97e-33398cfc89cd"}, {"title": "冯行袭讨山贼，蜀道复通", "start_year": 884, "end_year": 884, "time_original": "冯行袭任均州刺史后；具体月日未载", "dynasty": "唐", "description": "冯行袭讨伐占据长山、侵夺贡赋的群盗，使通往蜀地的道路恢复通行。", "phases": [], "location_name": "长山、蜀道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3cab7827-8a3b-56b3-b18a-1f45d7571746"}, {"title": "李昌言病故后李昌符承袭凤翔节度使", "start_year": 884, "end_year": 884, "time_original": "中和四年是岁条；具体月日未载", "dynasty": "唐", "description": "李昌言病时上表请弟李昌符知留后；李昌言死后，朝廷任李昌符为凤翔节度使。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bb2f875b-09ec-5447-84ba-a18db171f633"}, {"title": "《通鉴》总述秦宗权部侵扰诸道", "start_year": null, "end_year": null, "time_original": "黄巢平后秦宗权势炽；各次侵攻确年待考", "dynasty": "唐", "description": "《通鉴》在年末总述秦宗权命陈彦、秦贤、秦诰、孙儒、张晊、卢瑭等分路侵掠诸道，并记其所至焚杀严重；各地陷落不能仅据总述一律定于884年。", "phases": [], "location_name": "淮南、江南、襄唐邓、东都孟陕虢、汝郑、汴宋等", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "43e53c95-1909-5d4c-82f7-a7f350350aeb"}]'::jsonb)
