SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "高仁厚围梓州，致书城内劝降。郑君雄率众入府，杨师立自杀；郑君雄携首出降。", "citation": "卷256·中和四年（884）·zztj-v256-y0884-p001·原文件第6行", "note": "原文：六月，壬辰，东川留后高仁厚奏郑君雄斩杨师立出降。仁厚围梓州久不下，乃为书射城中，道其将士曰：“仁厚不忍城中玉石俱焚，为诸君缓师十日，使诸君自成其功。若十日不送师立首，当分见兵为五番，番分昼夜以攻之，于此甚逸，于彼必困矣。五日不下，四面俱进，克之必矣。诸君图之！”数日，君雄大呼于众曰：“天子所诛者元恶耳，他人无预也！”众呼万岁，大噪，突入府中，师立自杀，君雄挈其首出降。仁厚献其首及妻子于行在，陈敬瑄钉其子于城北，敬瑄三子出观之，钉者呼曰：“兹事行及汝曹，汝曹于后努力领取！”三子走马而返。以高仁厚为东川节度使。；核对说明：按该段原文整理；未载细节不补写。", "status": "draft", "id": "6e042237-78cb-547e-be56-5069aba6fda3", "subject_id": "4ad79a39-48c2-5fd4-b67a-c70bb55f62ad", "source_id": "a38849fc-5d04-59ee-ae04-1830b68b7d1a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "中和四年六月壬辰奏报；围城经过历时未详", "citation": "卷256·中和四年（884）·zztj-v256-y0884-p001·原文件第6行", "note": "原文：六月，壬辰，东川留后高仁厚奏郑君雄斩杨师立出降。仁厚围梓州久不下，乃为书射城中，道其将士曰：“仁厚不忍城中玉石俱焚，为诸君缓师十日，使诸君自成其功。若十日不送师立首，当分见兵为五番，番分昼夜以攻之，于此甚逸，于彼必困矣。五日不下，四面俱进，克之必矣。诸君图之！”数日，君雄大呼于众曰：“天子所诛者元恶耳，他人无预也！”众呼万岁，大噪，突入府中，师立自杀，君雄挈其首出降。仁厚献其首及妻子于行在，陈敬瑄钉其子于城北，敬瑄三子出观之，钉者呼曰：“兹事行及汝曹，汝曹于后努力领取！”三子走马而返。以高仁厚为东川节度使。；核对说明：依卷年定位；干支日未换算为公历日。", "status": "draft", "id": "f9b1c973-f0bc-500c-99a2-9863194a22e4", "subject_id": "4ad79a39-48c2-5fd4-b67a-c70bb55f62ad", "source_id": "a38849fc-5d04-59ee-ae04-1830b68b7d1a"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记载高仁厚：围城及奏报者。", "citation": "卷256·中和四年（884）·zztj-v256-y0884-p001·原文件第6行", "note": "原文：六月，壬辰，东川留后高仁厚奏郑君雄斩杨师立出降。仁厚围梓州久不下，乃为书射城中，道其将士曰：“仁厚不忍城中玉石俱焚，为诸君缓师十日，使诸君自成其功。若十日不送师立首，当分见兵为五番，番分昼夜以攻之，于此甚逸，于彼必困矣。五日不下，四面俱进，克之必矣。诸君图之！”数日，君雄大呼于众曰：“天子所诛者元恶耳，他人无预也！”众呼万岁，大噪，突入府中，师立自杀，君雄挈其首出降。仁厚献其首及妻子于行在，陈敬瑄钉其子于城北，敬瑄三子出观之，钉者呼曰：“兹事行及汝曹，汝曹于后努力领取！”三子走马而返。以高仁厚为东川节度使。；核对说明：按该段原文整理；只陈述引文支持的事实，不推定未载的日期。", "status": "draft", "id": "c840b7e7-22a2-5e2b-8c21-b4337a3849ec", "subject_id": "ff014a27-d630-52e3-8a2a-fc160fbb8c30", "source_id": "a38849f